-- 표준 존 목표 DDL · KS X 9101-1:2025 개정(안) v1.0 최종본 — 명사 68, 테이블 76
-- 생성: tools/gen_schema.py. 참고용(새 설치 설계·검토). 실제 DB 는 db/schema 의 기준선 + V0014 로 이 모양이 된다.
-- 테이블정의서와 다른 물리 선택 (이유는 tools/gen_schema.py 머리말):
--   · snake_case 이름  · 기본키 = 식별 키(UK), 표준 행 일련번호는 <표>_sequence_no 자동 증가 + 고유 인덱스
--   · 이벤트 월 파티션 표는 기본키에 파티션 시각 열 포함  · 등록자·수정자 FK 생략
-- =============================================================================

CREATE TABLE ksx.site ( -- 사업장
    site_sequence_no BIGINT GENERATED BY DEFAULT AS IDENTITY,
    enterprise_id VARCHAR(50) NOT NULL,
    creator_id VARCHAR(50),
    creation_date_time TIMESTAMP,
    modifier_id VARCHAR(50),
    modification_date_time TIMESTAMP,
    note VARCHAR(1000),
    site_id VARCHAR(50) NOT NULL,
    site_name VARCHAR(200),
    business_registration_number VARCHAR(50),
    dial_number VARCHAR(30),
    postal_code VARCHAR(10),
    base_address VARCHAR(1000),
    detail_address VARCHAR(1000),
    use_indicator BOOLEAN,
    lake_batch_id UUID,
    lake_source_system VARCHAR(50),
    lake_loaded_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    lake_record_hash CHAR(64),
    lake_shacl_status VARCHAR(10) NOT NULL DEFAULT 'PENDING' CHECK (lake_shacl_status IN ('PENDING','CONFORMS','VIOLATION')),
    CONSTRAINT pk_site PRIMARY KEY (enterprise_id, site_id)
);
CREATE UNIQUE INDEX ux_site_sequence_no ON ksx.site (site_sequence_no);
CREATE TABLE ksx.plant ( -- 공장
    plant_sequence_no BIGINT GENERATED BY DEFAULT AS IDENTITY,
